previewCss:
.darma-loader-darma-b17-cash-register { --accent: var(--loader-color, #0f766e); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 122px); height: calc(var(--loader-size, 122px) * .76); position: relative; }
.darma-loader-darma-b17-cash-register .darma-loader-darma-b17-cash-register__screen { position: absolute; left: 22%; right: 22%; top: 2%; height: 22%; border-radius: 5px; background: color-mix(in srgb, #0f172a 80%, transparent); box-shadow: inset 0 0 0 2px var(--accent); overflow: hidden; }
.darma-loader-darma-b17-cash-register .darma-loader-darma-b17-cash-register__screen::after { content: ''; position: absolute; left: 8%; top: 34%; width: 0; height: 32%; border-radius: 2px; background: var(--accent-2); animation: darma-loader-darma-b17-cash-register-till-total calc(var(--loader-speed, 1s) * 2.4) steps(4, end) infinite; }
.darma-loader-darma-b17-cash-register .darma-loader-darma-b17-cash-register__body { position: absolute; left: 6%; right: 6%; top: 26%; height: 46%; border-radius: 6px; background: linear-gradient(color-mix(in srgb, #fff 18%, var(--accent)), var(--accent)); }
.darma-loader-darma-b17-cash-register span { position: absolute; top: 40%; width: 14%; height: 16%; border-radius: 3px; background: color-mix(in srgb, #fff 72%, var(--accent)); animation: darma-loader-darma-b17-cash-register-till-key calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b17-cash-register span:nth-of-type(1) { left: 16%; }
.darma-loader-darma-b17-cash-register span:nth-of-type(2) { left: 43%; animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b17-cash-register span:nth-of-type(3) { left: 70%; animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b17-cash-register .darma-loader-darma-b17-cash-register__drawer { position: absolute; left: 10%; bottom: 2%; width: 66%; height: 22%; border-radius: 4px; background: linear-gradient(color-mix(in srgb, #000 12%, var(--accent-2)), var(--accent-2)); animation: darma-loader-darma-b17-cash-register-till-drawer calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.4, 0, .3, 1) infinite; }
@keyframes darma-loader-darma-b17-cash-register-till-key { 0%, 100% { transform: translateY(0); } 12% { transform: translateY(22%); } 26% { transform: translateY(0); } }
@keyframes darma-loader-darma-b17-cash-register-till-total { 0%, 12% { width: 0; } 100% { width: 76%; } }
@keyframes darma-loader-darma-b17-cash-register-till-drawer { 0%, 62% { transform: translateX(0); } 78%, 88% { transform: translateX(26%); } 100% { transform: translateX(0); } }

